","import React, { createContext, useContext, useEffect, useState, useCallback } from "react";

const STORAGE_KEY = "grc_vp_nav_collapsed";

interface NavCtx {
 collapsed: boolean;
 toggle: () => void;
 setCollapsed: (v: boolean) => void;
}

const NavContext = createContext<NavCtx>({ collapsed: false, toggle: () => {}, setCollapsed: () => {} });

function readInitial(): boolean {
 try {
 const stored = window.localStorage.getItem(STORAGE_KEY);
 if (stored === "true") return true;
 if (stored === "false") return false;
 } catch (e) {
 /* ignore */
 }
 // Tablet (<=1024px) defaults to collapsed.
 try {
 return window.matchMedia("(max-width: 1024px)").matches;
 } catch (e) {
 return false;
 }
}

export function NavProvider({ children }: { children: React.ReactNode }) {
 const [collapsed, setCollapsedState] = useState<boolean>(readInitial);

 useEffect(() => {
 try {
 window.localStorage.setItem(STORAGE_KEY, String(collapsed));
 } catch (e) {
 /* ignore */
 }
 }, [collapsed]);

 const toggle = useCallback(() => setCollapsedState(p => !p), []);
 const setCollapsed = useCallback((v: boolean) => setCollapsedState(v), []);

 return <NavContext.Provider value={{ collapsed, toggle, setCollapsed }}>{children}</NavContext.Provider>;
}

export const useNav = () => useContext(NavContext);
","import React, { createContext, useContext, useEffect, useState, useCallback } from "react";

type Theme = "light" | "dark";
const STORAGE_KEY = "grc_vp_theme";

interface ThemeCtx {
 theme: Theme;
 toggle: () => void;
}

const ThemeContext = createContext<ThemeCtx>({ theme: "dark", toggle: () => {} });

function readInitial(): Theme {
 try {
 const stored = window.localStorage.getItem(STORAGE_KEY);
 if (stored === "light" || stored === "dark") return stored;
 } catch (e) {
 /* ignore */
 }
 return "dark";
}

function applyThemeClass(theme: Theme) {
 const root = document.documentElement;
 root.classList.remove("grc-theme-light", "grc-theme-dark");
 root.classList.add(theme === "dark" ? "grc-theme-dark" : "grc-theme-light");
}

export function ThemeProvider({ children }: { children: React.ReactNode }) {
 const [theme, setTheme] = useState<Theme>(readInitial);

 useEffect(() => {
 applyThemeClass(theme);
 try {
 window.localStorage.setItem(STORAGE_KEY, theme);
 } catch (e) {
 /* ignore */
 }
 }, [theme]);

 const toggle = useCallback(() => {
 setTheme(prev => (prev === "dark" ? "light" : "dark"));
 }, []);

 return <ThemeContext.Provider value={{ theme, toggle }}>{children}</ThemeContext.Provider>;
}

export const useTheme = () => useContext(ThemeContext);
