","import type { Severity } from "../../data/mockData";

export interface SevMeta {
 label: string;
 icon: string;
 cssVar: string; // CSS custom property name holding an rgb triplet
}

// Maps our semantic severity to a design token alias (defined in tokens.css)
// and a Horizon icon. Never color alone — always icon + label too.
export const SEVERITY: Record<Severity, SevMeta> = {
 critical: { label: "Critical", icon: "triangle-exclamation-fill", cssVar: "--grc-critical" },
 high: { label: "High", icon: "exclamation-fill", cssVar: "--grc-high" },
 watch: { label: "Watch", icon: "circle-exclamation-outline", cssVar: "--grc-watch" },
 info: { label: "Information", icon: "circle-info-outline", cssVar: "--grc-info" },
 healthy: { label: "Healthy", icon: "circle-check-outline", cssVar: "--grc-healthy" },
 neutral: { label: "Neutral", icon: "circle-outline", cssVar: "--grc-neutral" }
};

export const sevColor = (s: Severity) => `rgb(var(${SEVERITY[s].cssVar}))`;

export const appetiteSeverity = (status: string): Severity => {
 switch (status) {
 case "above":
 case "breach":
 return "critical";
 case "approaching":
 return "watch";
 case "within":
 return "healthy";
 default:
 return "neutral";
 }
};

export const trendIcon = (dir?: string) =>
 dir === "up" ? "arrow-up-outline" : dir === "down" ? "arrow-down-outline" : "arrow-right-left-outline";
