];

export const POSTURE_CONTRIBUTORS: PostureContributor[] = raw.map(r => ({
 ...r,
 weight: POSTURE_WEIGHTS[r.key],
 weighted: +(r.subScore * POSTURE_WEIGHTS[r.key]).toFixed(2)
}));

