}
","import React from "react";
import { Card, SectionHead } from "../common/Card";
import { ProgressRing, Sparkline, MiniBar } from "../viz/Charts";
import { MiniHeatmap } from "../viz/Heatmap";
import { DOMAIN_CARDS, DomainCard, Severity } from "../../data/mockData";

function DomainViz({ card }: { card: DomainCard }) {
 switch (card.viz) {
 case "heatmap":
 return <MiniHeatmap />;
 case "ring":
 return <ProgressRing value={91} severity="high" size={56} />;
 case "radar":
 return <Sparkline data={card.spark} severity="watch" area width={110} height={46} />;
 case "funnel":
 return (
 <div style={{ display: "flex", flexDirection: "column", gap: 3, width: 90 }}>
 {[100, 72, 50].map((w, i) => <MiniBar key={i} value={w} severity="healthy" height={9} />)}
 </div>
 );
 case "progress":
 return (
 <div style={{ display: "flex", flexDirection: "column", gap: 4, width: 90 }}>
 <MiniBar value={62} severity="info" height={8} />
 <MiniBar value={38} severity="watch" height={8} />
 </div>
 );
 default:
 return <Sparkline data={card.spark} severity="info" width={110} height={46} />;
 }
}

export function DomainPulse({ onOpenTab }: { onOpenTab: (tab: string) => void }) {
 return (
 <section className="grc-section">
 <SectionHead icon="grid-four-outline" title="GRC Domain Pulse" hint="One click into each domain — connected intelligence across the GRC chain" />
 <div className="grc-pulse">
 {DOMAIN_CARDS.map(card => (
 <Card key={card.id} className="grc-pulse__card" accent={card.accent as Severity} icon={card.icon} title={card.title} onClick={() => onOpenTab(card.tab)}>
 <div className="grc-pulse__viz"><DomainViz card={card} /></div>
 <div className="grc-pulse__metrics">
 {card.metrics.map(m => (
 <div className="grc-pulse__metric" key={m.label}>
 <span>{m.label}</span><b>{m.value}</b>
 </div>
 ))}
 </div>
 </Card>
 ))}
 </div>
 </section>
 );
}
