import type { Severity } from "../../data/mockData";

const sevForScore = (n: number): Severity => (n >= 85 ? "healthy" : n >= 72 ? "watch" : n >= 60 ? "high" : "critical");
const val = (s: BuScore, key: string): number => s.components.find(c => c.key === key)?.value ?? 0;

export function BusinessUnits() {
