 <th>Rank</th><th>Business Unit</th><th>GRC Score</th><th>Risk</th><th>Control</th>
 <th>Compliance</th><th>Governance</th><th>Open Critical</th><th>Strength / Weakness</th><th>Trend</th>
 </tr>
 </thead>
 <tbody>
 {scores.map(s => (
 <tr key={s.bu} onClick={() => setSelector("businessUnit", s.bu)}
 style={selectors.businessUnit === s.bu ? { background: "rgba(var(--grc-primary),0.12)" } : undefined}>
