 <td><MiniBar value={val(s, "control")} severity={sevForScore(val(s, "control"))} /></td>
 <td><MiniBar value={val(s, "compliance")} severity={sevForScore(val(s, "compliance"))} /></td>
 <td><MiniBar value={val(s, "governance")} severity={sevForScore(val(s, "governance"))} /></td>
 <td style={{ fontWeight: 700, color: s.criticalItems > 0 ? "rgb(var(--grc-critical))" : "inherit" }}>{s.criticalItems}</td>
 <td className="grc-bu-sw">
 <span className="grc-bu-sw__up">▲ {s.topStrength.label}</span>
 <span className="grc-bu-sw__down">▼ {s.topWeakness.label}</span>
 </td>
 <td><span className="grc-bu-trend"><TrendArrow dir={s.trend} /></span></td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 </Card>
 </section>
 );
}
