// Returns the five labeled narrative sections (SIGNAL…RECOMMENDATION).
export function formatInsight(ins: ExecutiveInsight): { label: string; text: string }[] {
 return [
 { label: "SIGNAL", text: ins.signal },
 { label: "IMPACT", text: ins.impact },
 { label: "CAUSE", text: ins.cause },
 { label: "PREDICTION", text: ins.prediction },
 { label: "RECOMMENDATION", text: ins.recommendation }
