","import React from "react";
import { Forecast } from "../../data/risk/forecast";
import { sevColor } from "../viz/severity";

// Forecast area/line chart: current + 30/60/90 with appetite & tolerance threshold lines.
export function ForecastChart({ f }: { f: Forecast }) {
 const W = 440, H = 180, pad = 30;
 const pts = [f.current, f.f30, f.f60, f.f90];
 const all = [...pts, f.appetite, f.tolerance];
 const min = Math.min(...all) - 4;
 const max = Math.max(...all) + 4;
 const span = max - min || 1;
 const x = (i: number) => pad + (i / 3) * (W - pad * 2);
 const y = (v: number) => H - pad - ((v - min) / span) * (H - pad * 2);
 const line = pts.map((v, i) => `${x(i)},${y(v)}`).join(" L");
 const labels = ["Now", "+30d", "+60d", "+90d"];
 const thresh = (v: number, col: string, label: string) => (
 <g>
 <line x1={pad} y1={y(v)} x2={W - pad} y2={y(v)} stroke={col} strokeDasharray="4 4" strokeWidth="1.5" opacity="0.8" />
 <text x={W - pad} y={y(v) - 4} textAnchor="end" className="grc-heatmap__axis">{label} {v}</text>
 </g>
 );
 return (
 <svg width="100%" viewBox={`0 0 ${W} ${H}`} role="img" aria-label={`${f.category} forecast`}>
 {thresh(f.appetite, sevColor("high"), "Appetite")}
 {thresh(f.tolerance, sevColor("critical"), "Tolerance")}
 <path d={`M${line} L${x(3)},${H - pad} L${x(0)},${H - pad} Z`} fill={sevColor("watch")} opacity="0.12" />
 <path d={`M${line}`} fill="none" stroke={sevColor("watch")} strokeWidth="2.5" strokeLinecap="round" />
 {pts.map((v, i) => (
 <g key={i}>
 <circle cx={x(i)} cy={y(v)} r="3.5" fill={sevColor("watch")} />
 <text x={x(i)} y={y(v) - 9} textAnchor="middle" className="grc-heatmap__label">{v}</text>
 <text x={x(i)} y={H - pad + 14} textAnchor="middle" className="grc-heatmap__axis">{labels[i]}</text>
 </g>
 ))}
 </svg>
 );
}
