interface GNode { key: string; label: string; count: number; color: string; tab?: string }

const NODES: GNode[] = [
 { key: "controls", label: "Controls", count: OPERATIONAL_CONNECTIONS.controls, color: sevColor("healthy"), tab: "controls" },
 { key: "kris", label: "KRIs", count: OPERATIONAL_CONNECTIONS.kris, color: sevColor("high"), tab: "risk" },
 { key: "policies", label: "Policies", count: OPERATIONAL_CONNECTIONS.policies, color: sevColor("info"), tab: "governance" },
 { key: "regulations", label: "Regulations", count: OPERATIONAL_CONNECTIONS.regulations, color: sevColor("watch"), tab: "regulatory" },
 { key: "issues", label: "Issues", count: OPERATIONAL_CONNECTIONS.issues, color: sevColor("critical"), tab: "controls" },
 { key: "mitigations", label: "Mitigations", count: OPERATIONAL_CONNECTIONS.mitigations, color: sevColor("info"), tab: "risk" },
 { key: "businessUnits", label: "Business Units", count: OPERATIONAL_CONNECTIONS.businessUnits, color: sevColor("neutral"), tab: "risk" },
 { key: "assurance", label: "Assurance", count: OPERATIONAL_CONNECTIONS.assurance, color: sevColor("healthy"), tab: "assurance" }
];

export function RiskConnectionGraph({ onNavigate }: { onNavigate: (tab: string) => void }) {
 const W = 520, H = 360, cx = W / 2, cy = H / 2, r = 128;
 return (
 <section className="grc-section">
 <SectionHead icon="hierarchy-2-outline" title="Risk Connection Graph" hint="Operational Risk and its connected controls, KRIs, policies, regulations, issues, mitigations, BUs and assurance" />
 <Card>
 <svg width="100%" viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Operational risk connection graph">
 {NODES.map((n, i) => {
 const a = (i / NODES.length) * Math.PI * 2 - Math.PI / 2;
 const nx = cx + Math.cos(a) * r, ny = cy + Math.sin(a) * r;
 return <line key={`l${n.key}`} x1={cx} y1={cy} x2={nx} y2={ny} stroke="rgba(var(--grc-track),0.9)" strokeWidth="1.5" />;
 })}
 {NODES.map((n, i) => {
 const a = (i / NODES.length) * Math.PI * 2 - Math.PI / 2;
 const nx = cx + Math.cos(a) * r, ny = cy + Math.sin(a) * r;
 return (
 <g key={n.key} className="grc-heatmap__bubble" role="button" tabIndex={0} onClick={() => n.tab && onNavigate(n.tab)}>
 <circle cx={nx} cy={ny} r="26" fill={n.color} fillOpacity="0.22" stroke={n.color} strokeWidth="2" />
 <text x={nx} y={ny - 1} textAnchor="middle" className="grc-graph__count">{n.count}</text>
 <text x={nx} y={ny + 36} textAnchor="middle" className="grc-heatmap__label">{n.label}</text>
 </g>
 );
 })}
 <circle cx={cx} cy={cy} r="40" fill={sevColor("critical")} fillOpacity="0.25" stroke={sevColor("critical")} strokeWidth="2.5" />
 <text x={cx} y={cy - 2} textAnchor="middle" className="grc-graph__center">Operational</text>
 <text x={cx} y={cy + 14} textAnchor="middle" className="grc-graph__center">82.1</text>
 </svg>
 </Card>
 </section>
 );
}
