 <span className="grc-inssec__label">{s.label}</span>
 <p className="grc-inssec__text">{s.text}</p>
 </div>
 ))}
 {ins.recommendedActions && ins.recommendedActions.length ? (
 <div className="grc-inssec">
 <span className="grc-inssec__label">AI RECOMMENDED ACTIONS</span>
 <ol className="grc-recactions">{ins.recommendedActions.map((a, i) => <li key={i}>{a}</li>)}</ol>
 </div>
 ) : null}
 </div>
 );
}
","import React, { useEffect } from "react";
import { Button } from "@servicenow/react-components/Button";
import { Icon } from "@servicenow/react-components/Icon";
import { StatusPill, TrendArrow } from "../viz/Indicators";
import { Sparkline, MicroBars } from "../viz/Charts";
import { useActions } from "../common/Actions";
