import { evaluateStatus, statusLabel } from "../../logic/thresholds";
import { Field, ThresholdBar, DriverRows, BuContributors, RelatedGroups, InsightBlock } from "./KpiDrawerParts";

export function KpiDrawer({ kpiId, onClose, onOpenIssue, onOpenTab }: {
