 return () => document.removeEventListener("keydown", onKey);
 }, [onClose]);

 if (!kpi) return null;
 const sev = evaluateStatus(kpi.value, { target: kpi.target, warning: kpi.warningThreshold, critical: kpi.criticalThreshold }, kpi.higherIsBetter);
 const unitSuffix = kpi.unit === "%" ? "%" : "";
 const openAnalysis = () => { onOpenTab(kpi.tab); onClose(); };

 return (
