","import { useState, useEffect, useCallback } from "react";

export interface RouteState {
 tab: string;
 view: string | null; // e.g. "detail" | "kpi" | "risk"
 id: string | null;
 sub: string | null; // risk sub-view (overview, categories, …)
}

export function getRouteFromUrl(): RouteState {
 const params = new URLSearchParams(window.location.search);
 return {
 tab: params.get("tab") || "overview",
 view: params.get("view"),
 id: params.get("id"),
 sub: params.get("sub")
 };
}

function buildPath(next: RouteState): string {
 const params = new URLSearchParams();
 params.set("tab", next.tab);
 if (next.view) params.set("view", next.view);
 if (next.id) params.set("id", next.id);
 if (next.sub) params.set("sub", next.sub);
 return `${window.location.pathname}?${params.toString()}`;
}

function pushTitle(path: string, title: string) {
 if (window.self !== window.top) {
 try {
 (window as any).CustomEvent.fireTop("magellanNavigator.permalink.set", {
 relativePath: path,
 title
 });
 } catch (e) {
 /* ignore */
 }
 }
 window.history.pushState({}, "", path);
 document.title = title;
}

export function useRouter() {
 const [route, setRoute] = useState<RouteState>(getRouteFromUrl);

 useEffect(() => {
 const onPop = () => setRoute(getRouteFromUrl());
 window.addEventListener("popstate", onPop);
 return () => window.removeEventListener("popstate", onPop);
 }, []);

 const navigate = useCallback((next: Partial<RouteState>, title?: string) => {
 setRoute(prev => {
 const merged: RouteState = {
 tab: next.tab !== undefined ? (next.tab as string) : prev.tab,
 view: next.view !== undefined ? next.view : prev.view ?? null,
 id: next.id !== undefined ? next.id : prev.id ?? null,
 sub: next.sub !== undefined ? next.sub : prev.sub ?? null
 };
 const path = buildPath(merged);
 pushTitle(path, title || `GRC VP Command Center`);
 return merged;
 });
 }, []);

 const goTab = useCallback(
 (tab: string, title?: string) => {
 const merged: RouteState = { tab, view: null, id: null, sub: null };
 const path = buildPath(merged);
 pushTitle(path, title || `GRC VP Command Center`);
 setRoute(merged);
 },
 []
 );

 const setSub = useCallback((sub: string | null, title?: string) => {
 setRoute(prev => {
 const merged: RouteState = { ...prev, sub };
 const path = buildPath(merged);
 pushTitle(path, title || `GRC VP Command Center`);
 return merged;
 });
 }, []);

 return { route, navigate, goTab, setSub };
}
","import React, { useCallback } from "react";
import "./styles/tokens.css";
import "./styles/layout.css";
import "./styles/sections.css";
import "./styles/overrides.css";
import "./styles/risk.css";
import "./styles/fixes.css";

import { Header } from "./components/layout/Header";
import { Sidebar } from "./components/layout/Sidebar";
import { Breadcrumbs } from "./components/layout/TabNav";
import { ExecutiveOverview } from "./components/overview/ExecutiveOverview";
import { TabView } from "./components/tabs/TabView";
import { EnterpriseRisk } from "./components/risk/EnterpriseRisk";
import { IssueDrawer } from "./components/drawer/IssueDrawer";
import { KpiDrawer } from "./components/drawer/KpiDrawer";
import { RiskDrawer } from "./components/drawer/RiskDrawer";
import { AiPanel } from "./components/ai/AiPanel";
import { FloatingAi } from "./components/ai/FloatingAi";
import { useRouter } from "./router/useRouter";
import { useApp } from "./context/AppContext";
import { useNav } from "./context/NavContext";
import { TABS, Kpi, RiskBubble } from "./data/mockData";
import { ISSUES } from "./data/content";
import { getKpi } from "./data/kpis";
import { riskSubLabel } from "./data/risk/subnav";

function pageTitleFor(tab: string): string {
 if (tab === "risk") return "Enterprise Risk Intelligence";
 return TABS.find(t => t.id === tab)?.label || "Executive Overview";
}
function docTitle(tab: string) { return `GRC VP Command Center — ${pageTitleFor(tab)}`; }

function mapRiskToIssue(r: RiskBubble): string {
 const byBu = ISSUES.find(i => i.bu === r.bu);
 return byBu ? byBu.id : ISSUES[0].id;
}

export default function App() {
 const { route, navigate, goTab } = useRouter();
 const { aiPanelOpen, setAiPanelOpen } = useApp();
 const { collapsed } = useNav();

 const openIssue = useCallback((id: string) => {
 const issue = ISSUES.find(i => i.id === id);
 navigate({ view: "detail", id }, `GRC — ${issue?.issue || "Issue"}`);
 }, [navigate]);

 const openRisk = useCallback((id: string) => navigate({ view: "risk", id }, "GRC — Risk Detail"), [navigate]);
 const closeDrawer = useCallback(() => navigate({ view: null, id: null }, docTitle(route.tab)), [navigate, route.tab]);
 const onOpenTab = useCallback((tab: string) => goTab(tab, docTitle(tab)), [goTab]);
 const onSelectSub = useCallback((sub: string) => navigate({ sub }, docTitle("risk")), [navigate]);
 const onSelectRisk = useCallback((r: RiskBubble) => openIssue(mapRiskToIssue(r)), [openIssue]);

 const onOpenKpi = useCallback((k: Kpi | string) => {
 const id = typeof k === "string" ? k : k.id;
 const name = getKpi(id)?.name || (typeof k === "string" ? id : k.title);
 navigate({ view: "kpi", id }, `GRC — ${name}`);
 }, [navigate]);

 const activeTab = TABS.find(t => t.id === route.tab);
 const drawerIssueId = route.view === "detail" ? route.id : null;
 const drawerKpiId = route.view === "kpi" ? route.id : null;
 const drawerRiskId = route.view === "risk" ? route.id : null;
 const showAiPanel = route.tab !== "ai";

 const crumbs: { label: string; onClick?: () => void }[] = [
 { label: "Executive Overview", onClick: () => onOpenTab("overview") }
 ];
 if (route.tab !== "overview") crumbs.push({ label: activeTab?.label || route.tab, onClick: () => onOpenTab(route.tab) });
 if (route.tab === "risk") crumbs.push({ label: riskSubLabel(route.sub) });
 if (drawerIssueId) crumbs.push({ label: ISSUES.find(i => i.id === drawerIssueId)?.issue || "Issue" });
 if (drawerKpiId) crumbs.push({ label: getKpi(drawerKpiId)?.name || "KPI" });

 const breadcrumb = `GRC VP Command Center › ${pageTitleFor(route.tab)}`;

 return (
 <div className={`grc-app ${collapsed ? "grc-app--navcollapsed" : ""}`}>
 <div className="grc-shell">
 <Header onToggleAi={() => setAiPanelOpen(!aiPanelOpen)} pageTitle={pageTitleFor(route.tab)} breadcrumb={breadcrumb} />
 <div className="grc-body">
 <Sidebar active={route.tab} sub={route.sub} onSelect={onOpenTab} onSelectSub={onSelectSub} />
 <main className="grc-main">
 {(route.tab !== "overview" || drawerIssueId || drawerKpiId) ? <Breadcrumbs items={crumbs} /> : null}
 {route.tab === "overview"
 ? <ExecutiveOverview onOpenTab={onOpenTab} onOpenIssue={openIssue} onSelectRisk={onSelectRisk} onOpenKpi={onOpenKpi} />
 : route.tab === "risk"
 ? <EnterpriseRisk sub={route.sub} onOpenRisk={openRisk} onOpenTab={onOpenTab} onSetSub={onSelectSub} />
 : <TabView tab={route.tab} onOpenIssue={openIssue} onSelectRisk={onSelectRisk} />}
 </main>
 {showAiPanel ? <AiPanel open={aiPanelOpen} onToggle={() => setAiPanelOpen(!aiPanelOpen)} /> : null}
 </div>
 </div>

 {drawerIssueId ? <IssueDrawer issueId={drawerIssueId} onClose={closeDrawer} /> : null}
 {drawerKpiId ? <KpiDrawer kpiId={drawerKpiId} onClose={closeDrawer} onOpenIssue={openIssue} onOpenTab={onOpenTab} /> : null}
 {drawerRiskId ? <RiskDrawer riskId={drawerRiskId} onClose={closeDrawer} onOpenTab={onOpenTab} /> : null}
 <FloatingAi panelOpen={showAiPanel && aiPanelOpen} tab={route.tab} />
 </div>
 );
}
","import React from "react";
