 ReactDOM.createRoot(container).render(
 <ThemeProvider>
 <AppProvider>
 <NavProvider>
 <ActionsProvider>
 <App />
 </ActionsProvider>
 </NavProvider>
 </AppProvider>
 </ThemeProvider>
 );
}
